/* ==UserStyle==
@name           Gruvbox-Jira
@namespace      github.com/rdruker/dotfiles/stylus
@version        2026.10.01
@description    Gruvbox Material dark for Jira Cloud, Jira DC and the JSM portal. Based on Kloud's Jira Gruvbox Dark (userstyles.world/style/29575, CC0).
@author         Ronen Druker
@license        CC0
==/UserStyle== */

/* tps-jira matches everything except Plans and Tempo (styled by Gruvbox-Jira-Plans-Tempo). */
@-moz-document domain("atlassian.net"), domain("cdn.prod.atlassian-dev.net"),
  domain("tps-git.topcon.com"),
  regexp("https?://tps-jira\\.topcon\\.com/(?!secure/(PortfolioPlanView|Tempo)\\.jspa).*") {
:root,
  html[data-color-mode],
  html[data-theme] {
    color-scheme: dark !important;

    /* Gruvbox palette */
    --gb-bg-hard: #1b1b1b;
    --gb-bg: #282828;
    --gb-bg-soft: #32302f;
    --gb-bg-1: #3c3836;
    --gb-bg-2: #504945;
    --gb-bg-3: #5a524c;
    --gb-fg: #ddc7a1;
    --gb-fg-muted: #d4be98;
    --gb-fg-dim: #a89984;
    --gb-red: #ea6962;
    --gb-green: #a9b665;
    --gb-yellow: #d8a657;
    --gb-blue: #7daea3;
    --gb-purple: #d3869b;
    --gb-aqua: #89b482;
    --gb-orange: #e78a4e;

    /* Atlassian surfaces */
    --ds-surface: var(--gb-bg) !important;
    --ds-surface-raised: var(--gb-bg-soft) !important;
    --ds-surface-overlay: var(--gb-bg-1) !important;
    --ds-surface-sunken: var(--gb-bg-hard) !important;
    --ds-surface-hovered: var(--gb-bg-1) !important;
    --ds-surface-pressed: var(--gb-bg-2) !important;
    --ds-surface-selected: #374141 !important;
    --ds-surface-selected-hovered: #3d4a47 !important;
    --ds-elevation-surface: var(--gb-bg) !important;
    --ds-elevation-surface-raised: var(--gb-bg-soft) !important;
    --ds-elevation-surface-overlay: var(--gb-bg-1) !important;
    --ds-elevation-surface-sunken: var(--gb-bg-hard) !important;

    /* Atlassian backgrounds */
    --ds-background-neutral: var(--gb-bg-1) !important;
    --ds-background-neutral-subtle: transparent !important;
    --ds-background-neutral-hovered: var(--gb-bg-1) !important;
    --ds-background-neutral-pressed: var(--gb-bg-2) !important;
    --ds-background-neutral-bold: var(--gb-fg-dim) !important;
    --ds-background-selected: #374141 !important;
    --ds-background-selected-hovered: #3d4a47 !important;
    --ds-background-brand-bold: #61827b !important;
    --ds-background-brand-bold-hovered: #719b91 !important;
    --ds-background-brand-bold-pressed: #4e645f !important;
    --ds-background-brand-subtlest: #333a39 !important;
    --ds-background-brand-subtlest-hovered: #3c4745 !important;
    --ds-background-danger: #4c3432 !important;
    --ds-background-danger-hovered: #593837 !important;
    --ds-background-danger-bold: #944c48 !important;
    --ds-background-warning: #4f422e !important;
    --ds-background-warning-bold: #8f7243 !important;
    --ds-background-success: #3b4439 !important;
    --ds-background-success-bold: #6c7348 !important;
    --ds-background-information: #374141 !important;
    --ds-background-information-bold: #5b7872 !important;
    --ds-background-discovery: #443840 !important;
    --ds-background-discovery-bold: #90616e !important;
    --ds-background-accent-blue-subtlest: #374141 !important;
    --ds-background-accent-blue-subtler: #3e4b48 !important;
    --ds-background-accent-blue-subtle: #4f6560 !important;
    --ds-background-accent-blue-bolder: #7daea3 !important;

    /* Text and links */
    --ds-text: var(--gb-fg) !important;
    --ds-text-subtle: var(--gb-fg-muted) !important;
    --ds-text-subtlest: var(--gb-fg-dim) !important;
    --ds-text-disabled: #5a524c !important;
    --ds-text-inverse: var(--gb-bg-hard) !important;
    --ds-text-brand: var(--gb-blue) !important;
    --ds-text-selected: var(--gb-blue) !important;
    --ds-text-information: var(--gb-blue) !important;
    --ds-text-success: var(--gb-green) !important;
    --ds-text-warning: var(--gb-yellow) !important;
    --ds-text-danger: var(--gb-red) !important;
    --ds-text-discovery: var(--gb-purple) !important;
    --ds-link: var(--gb-blue) !important;
    --ds-link-pressed: var(--gb-blue) !important;

    /* Borders, controls, and focus */
    --ds-border: var(--gb-bg-2) !important;
    --ds-border-bold: var(--gb-bg-3) !important;
    --ds-border-focused: var(--gb-blue) !important;
    --ds-border-selected: var(--gb-blue) !important;
    --ds-border-input: var(--gb-bg-3) !important;
    --ds-border-danger: var(--gb-red) !important;
    --ds-icon: var(--gb-fg-muted) !important;
    --ds-icon-subtle: var(--gb-fg-dim) !important;
    --ds-icon-brand: var(--gb-blue) !important;
    --ds-icon-selected: var(--gb-blue) !important;
    --ds-icon-danger: var(--gb-red) !important;
    --ds-blanket: rgb(27 27 27 / 78%) !important;
    --ds-shadow-overlay: 0 8px 24px rgb(0 0 0 / 50%) !important;
    --ds-shadow-raised: 0 2px 8px rgb(0 0 0 / 35%) !important;
  }

  html,
  body,
  #root,
  #app,
  #jira,
  [data-testid="page-layout.root"] {
    background: var(--gb-bg) !important;
    color: var(--gb-fg) !important;
  }

  body {
    scrollbar-color: var(--gb-bg-3) var(--gb-bg-hard);
  }

  ::selection {
    color: var(--gb-bg-hard);
    background: var(--gb-yellow);
  }

  /* Top navigation and sidebars */
  header,
  nav,
  [role="navigation"],
  [data-testid*="navigation"],
  [data-testid*="sidebar"] {
    border-color: var(--gb-bg-2) !important;
  }

  header,
  [role="banner"],
  [data-vc="top-nav"],
  [data-testid="atlassian-navigation--header"],
  [data-testid*="global-navigation"],
  [data-testid*="top-navigation"],
  [data-testid*="top-nav"] {
    background: linear-gradient(90deg, var(--gb-bg-hard), var(--gb-bg)) !important;
    color: var(--gb-fg) !important;
    border-color: var(--gb-bg-2) !important;
    box-shadow: 0 1px 0 var(--gb-bg-2) !important;
  }

  header > div,
  [role="banner"] > div,
  [data-vc="top-nav"] > div,
  [data-testid="atlassian-navigation--header"] > div {
    background-color: transparent !important;
    border-color: var(--gb-bg-2) !important;
  }

  header input,
  [role="banner"] input,
  [data-vc="top-nav"] input {
    background-color: var(--gb-bg-soft) !important;
  }

  /* Cards, panels, dialogs, and menus */
  [role="dialog"],
  [role="menu"],
  [role="listbox"],
  [data-testid*="modal"],
  [data-testid*="popover"],
  [data-testid*="dropdown"],
  [data-testid*="card"] {
    color: var(--gb-fg) !important;
    border-color: var(--gb-bg-2) !important;
  }

  [role="dialog"],
  [role="menu"],
  [role="listbox"] {
    background-color: var(--gb-bg-soft) !important;
    box-shadow: 0 12px 36px rgb(0 0 0 / 55%) !important;
  }

  /* Inputs and editors */
  input,
  textarea,
  select,
  [contenteditable="true"],
  [role="textbox"] {
    color: var(--gb-fg) !important;
    caret-color: var(--gb-yellow) !important;
    background-color: var(--gb-bg-hard) !important;
    border-color: var(--gb-bg-3) !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: var(--gb-fg-dim) !important;
    opacity: 1 !important;
  }

  input:focus,
  textarea:focus,
  select:focus,
  [contenteditable="true"]:focus,
  [role="textbox"]:focus {
    border-color: var(--gb-blue) !important;
    box-shadow: 0 0 0 2px rgb(125 174 163 / 25%) !important;
    outline: none !important;
  }

  /* Links */
  a:not([role="button"]) {
    color: var(--gb-blue) !important;
    text-decoration-color: rgb(125 174 163 / 45%) !important;
  }

  a:not([role="button"]):hover {
    color: var(--gb-blue) !important;
    text-decoration-color: currentColor !important;
  }

  /* Project/space tabs are navigation labels, not content links. */
  nav[aria-label="Space navigation"]
    [data-testid="navigation-kit-ui-tab.ui.link-tab"],
  nav[aria-label="Space navigation"]
    [data-testid="navigation-kit-ui-tab-list.ui.more-trigger.more-tab"] {
    color: var(--gb-fg-muted) !important;
    text-decoration: none !important;
  }

  nav[aria-label="Space navigation"]
    [data-testid="navigation-kit-ui-tab.ui.link-tab"]:hover,
  nav[aria-label="Space navigation"]
    [data-testid="navigation-kit-ui-tab-list.ui.more-trigger.more-tab"]:hover {
    color: var(--gb-fg) !important;
  }

  nav[aria-label="Space navigation"] [aria-current="page"] {
    color: var(--gb-yellow) !important;
  }

  /* Buttons */
  button {
    border-color: transparent;
  }

  button[aria-pressed="true"],
  [role="button"][aria-pressed="true"],
  [aria-selected="true"] {
    color: var(--gb-blue) !important;
    background-color: #374141 !important;
  }

  button:focus-visible,
  [role="button"]:focus-visible,
  a:focus-visible {
    outline: 2px solid var(--gb-yellow) !important;
    outline-offset: 2px !important;
  }

  /* Issue tables and backlog rows */
  table {
    color: var(--gb-fg) !important;
    background-color: var(--gb-bg) !important;
    border-color: var(--gb-bg-2) !important;
  }

  th {
    color: var(--gb-fg-muted) !important;
    background-color: var(--gb-bg-soft) !important;
    border-color: var(--gb-bg-2) !important;
  }

  td,
  tr {
    border-color: var(--gb-bg-1) !important;
  }

  tbody tr:hover,
  [data-testid*="issue-row"]:hover,
  [data-testid*="list-item"]:hover {
    background-color: var(--gb-bg-1) !important;
  }

  /* Issue Navigator detail-view results */
  [data-testid="issue-navigator.ui.issue-results.detail-view.card-list.card.list-item"] {
    background: var(--gb-bg) !important;
  }

  [data-testid="issue-navigator.ui.issue-results.detail-view.card-list.card"] {
    --_17wxfjt: var(--gb-bg-soft) !important;
    color: var(--gb-fg) !important;
    background: var(--gb-bg-soft) !important;
    border-color: var(--gb-bg-2) !important;
    box-shadow: inset 3px 0 0 transparent !important;
  }

  [data-testid="issue-navigator.ui.issue-results.detail-view.card-list.card"]:hover {
    --_17wxfjt: var(--gb-bg-1) !important;
    background: var(--gb-bg-1) !important;
    border-color: var(--gb-bg-3) !important;
  }

  [data-testid="issue-navigator.ui.issue-results.detail-view.card-list.card"][aria-current="true"],
  [data-testid="issue-navigator.ui.issue-results.detail-view.card-list.card"][aria-selected="true"],
  [data-testid="issue-navigator.ui.issue-results.detail-view.card-list.card"]:focus {
    --_17wxfjt: #374141 !important;
    background: #374141 !important;
    box-shadow: inset 3px 0 0 var(--gb-blue) !important;
  }

  [data-testid="issue-navigator.ui.issue-results.detail-view.card-list.card.summary"] {
    color: var(--gb-fg) !important;
  }

  /* Kanban and scrum boards */
  [data-testid*="board"],
  [data-testid*="backlog"] {
    border-color: var(--gb-bg-2) !important;
  }

  [data-testid*="column"] {
    border-color: var(--gb-bg-2) !important;
  }

  [data-testid*="issue-card"],
  [class*="issue-card"],
  [class*="IssueCard"] {
    background-color: var(--gb-bg-soft) !important;
    border-color: var(--gb-bg-2) !important;
    box-shadow: 0 1px 2px rgb(0 0 0 / 35%) !important;
  }

  [data-testid*="issue-card"]:hover,
  [class*="issue-card"]:hover,
  [class*="IssueCard"]:hover {
    background-color: var(--gb-bg-1) !important;
    border-color: var(--gb-bg-3) !important;
    box-shadow: 0 4px 12px rgb(0 0 0 / 35%) !important;
  }

  /* Code, preformatted text, and inline mentions */
  code,
  pre,
  kbd,
  samp {
    color: var(--gb-fg) !important;
    background-color: var(--gb-bg-soft) !important;
    border-color: var(--gb-bg-2) !important;
  }

  pre {
    box-shadow: inset 3px 0 0 var(--gb-orange);
  }

  [data-mention-id],
  [data-testid*="mention"] {
    color: var(--gb-blue) !important;
    background-color: #374141 !important;
  }

  /* Status lozenges: preserve meaning with Gruvbox accents */
  [data-testid*="status"],
  [class*="Status"] {
    border-color: rgb(212 190 152 / 12%) !important;
  }

  /* Images and avatars should remain natural. */
  img,
  video,
  canvas,
  [data-testid*="avatar"] {
    filter: none !important;
  }

  /* Less glare from embedded white content. */
  iframe {
    background-color: var(--gb-bg) !important;
  }

  /* Atlassian Forge app containers and their cross-origin iframe pages */
  div[role="status"]:has([data-testid="hosted-resources-iframe-container"]),
  [data-testid="hosted-resources-iframe-container"],
  [data-testid="hosted-resources-iframe-container"] > div {
    color: var(--gb-fg) !important;
    background: var(--gb-bg) !important;
  }

  iframe[data-forge-iframe="true"],
  iframe[data-testid="hosted-resources-iframe"] {
    color-scheme: dark !important;
    background: var(--gb-bg) !important;
  }

  body > #root,
  body > #app,
  body > div:first-child:not(#aui-flag-container) {
    min-height: 100%;
    background-color: var(--gb-bg) !important;
  }

  /* Compact, rounded Jira polish */
  [role="dialog"],
  [role="menu"],
  [role="listbox"],
  [data-testid*="issue-card"],
  [class*="issue-card"],
  [class*="IssueCard"] {
    border-radius: 8px !important;
  }

  * {
    scrollbar-width: thin;
  }

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: var(--gb-bg-hard);
  }

  ::-webkit-scrollbar-thumb {
    background: var(--gb-bg-3);
    border: 2px solid var(--gb-bg-hard);
    border-radius: 999px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--gb-fg-dim);
  }
  /* Jira DC notification flags: #aui-flag-container is body's first child, so the
     full-height page background above turned it into an opaque strip covering the
     right side of the page until every flag was closed. Keep it see-through. */
  #aui-flag-container {
    min-height: 0 !important;
    background: transparent !important;
  }

  /* Jira Service Management customer portal (help center) */
  :root,
  html[data-color-mode],
  html[data-theme] {
    --ds-background-selected-bold: var(--gb-blue) !important;
    --ds-background-selected-bold-hovered: #8fbcb1 !important;
  }

  [data-testid="layout-banner"] {
    background-color: var(--gb-bg-soft) !important;
    background-image: linear-gradient(90deg, var(--gb-bg-hard), var(--gb-bg-soft)) !important;
  }

  [data-test-id="request-details.status-lozenge"] span {
    color: var(--gb-blue) !important;
    background-color: #374141 !important;
  }

  /* Portal branding paints link-style buttons ("Show details") navy with !important;
     the emotion class names are hashes of that branded rule. */
  [data-testid="main"] button.css-14soozb,
  [data-testid="main"] .css-mmrie {
    color: var(--gb-blue) !important;
  }

  button[data-testid="collapsed-editor"] {
    color: var(--gb-fg-dim) !important;
    background-color: var(--gb-bg-hard) !important;
    border: 1px solid var(--gb-bg-3) !important;
  }

  /* Atlaskit editor: the frame was white around the dark contenteditable. */
  .akEditor {
    color: var(--gb-fg) !important;
    background-color: var(--gb-bg-hard) !important;
    border-color: var(--gb-bg-3) !important;
  }

  .akEditor .ProseMirror[contenteditable="true"] {
    background-color: transparent !important;
    border-color: transparent !important;
    box-shadow: none !important;
  }

  /* Jira DC issue view: Tempo panel and time-tracking bars (inline colours). */
  [data-testid="tempoIssueViewPanel"] {
    color: var(--gb-fg) !important;
    background-color: var(--gb-bg) !important;
  }
  #tempo-issue-app button {
    color: var(--gb-fg) !important;
    background-color: var(--gb-bg-1) !important;
    border-color: var(--gb-bg-2) !important;
  }
  #tempo-issue-app button:hover { background-color: #45403d !important; }
  tr.tt_graph td[style*="#89afd7"] { background-color: var(--gb-blue) !important; }
  tr.tt_graph td[style*="#ec8e00"] { background-color: var(--gb-orange) !important; }
  tr.tt_graph td[style*="#51a825"] { background-color: var(--gb-green) !important; }
  tr.tt_graph td[style*="#cccccc"] { background-color: var(--gb-bg-2) !important; }
  #tempo-issue-app tr,
  #tempo-issue-app td { background-color: var(--gb-bg) !important; }
  #tempo-issue-app tr:hover,
  #tempo-issue-app tr:hover td { background-color: var(--gb-bg-soft) !important; }

  /* JSM help-center home: hero banner with the portal's branded image. */
  [data-testid="hero-element-background"],
  [data-testid="layout-section-box-wrapper"]:has([data-testid="hero-element-background"]),
  [data-testid="layout-section-box-wrapper"]:has([data-testid="hero-element-background"]) > [data-testid="layout-section"] {
    background-color: var(--gb-bg-soft) !important;
    background-image: linear-gradient(90deg, var(--gb-bg-hard), var(--gb-bg-soft)) !important;
  }

}

@-moz-document regexp("https://tps-testrail\\.topcon\\.com/+index\\.php\\?/ext/jira/.*") {
  /* TestRail panels embedded in Jira issues. Chrome paints an opaque white backdrop
     behind an iframe whose color-scheme differs from its parent, so declare dark. */
  :root {
    color-scheme: dark !important;
    background: transparent !important;
  }
  body {
    color: #ddc7a1 !important;
    background: transparent !important;
  }
  a { color: #7daea3 !important; }
  a.button {
    color: #282828 !important;
    background: #7daea3 !important;
    border-color: #7daea3 !important;
  }
}

